parameters.jsCode:
// Drops duplicates and gives each work a stable citation key.
const raw = $input.first().json.structuredOutput?.corpus ?? [];
const seen = new Set();
const used = {};
const corpus = [];
for (const p of raw) {
  const id = String(p.doi || p.title || '').toLowerCase();
  if (!id || seen.has(id)) continue;
  seen.add(id);
  const surname = String(p.authors?.[0] ?? 'Anon').split(' ').pop().normalize('NFKD').replace(/[^A-Za-z]/g, '') || 'Anon';
  const base = surname + (p.year ?? '');
  used[base] = (used[base] ?? 0) + 1;
  corpus.push({ ...p, key: used[base] > 1 ? base + String.fromCharCode(95 + used[base]) : base });
}
return [{ json: { corpus: corpus.slice(0, $('Task').first().json.max_sources) } }];

const corpus = $('Corpus').first().json.corpus;
const answer = $input.first().json;
const drop = new Set(String(answer.exclude ?? '').split(/[^0-9]+/).filter(Boolean).map(Number));
return corpus.filter((_, i) => !drop.has(i + 1)).map((paper) => ({ json: paper }));

