const list = $('Papers').all().map((i) => i.json);
const texts = $input.all().map((i) => String(i.json.text ?? ''));
const cards = texts.join('\n\n');
const corpusMeta = list.map(({ abstract, ...meta }) => meta);
const abstractOnly = texts.filter((t) => /abstract only|Material analyzed:\s*\**\s*abstract/i.test(t)).length;
return [{ json: { cards, corpusMeta, total: list.length, fullText: list.length - abstractOnly } }];

