parameters.jsCode:
const r = $input.first().json;
const passed = r.score >= 70 && r.critical.length === 0;
const bib = (String(r.text).match(/```bibtex\s*([\s\S]*?)```/) ?? [])[1]?.trim() ?? '';
const article = String(r.text).replace(/```bibtex[\s\S]*?```/, '').trim();
const cards = $('Collect Cards').first().json;
const sources = cards.corpusMeta.map((p, i) => `${i + 1}. [${p.key}] ${p.title} (${p.year ?? 'n.d.'}) ${p.doi ? 'https://doi.org/' + p.doi : (p.landing_url ?? p.pdf_url ?? '')}`).join('\n');
const open = r.critical.length ? '\n\n## Open critical issues\n' + r.critical.map((c, i) => `${i + 1}. ${c}`).join('\n') : '';
const file = (body, fileName, mimeType) => ({ data: Buffer.from(body, 'utf8').toString('base64'), fileName, mimeType });
const task = $('Task').first().json;
return [{
  json: { email: task.email, topic: task.topic, language: task.language, passed, score: r.score, recommendation: r.recommendation, rounds: r.round, critical: r.critical, sources: cards.total, fullText: cards.fullText },
  binary: {
    article: file(article, 'article.md', 'text/markdown'),
    bib: file(bib || '% The Editor returned no BibTeX block', 'references.bib', 'application/x-bibtex'),
    review: file(`# Review (round ${r.round}, score ${r.score}%, ${r.recommendation})${open}\n\n${r.review}`, 'review.md', 'text/markdown'),
    corpus: file(sources + '\n\n---\n\n' + cards.cards, 'sources-and-cards.md', 'text/markdown'),
  },
}];

